'use strict';
document.addEventListener('DOMContentLoaded', function() {
  var reqElem = document.getElementById('val-requests');
  var latElem = document.getElementById('val-latency');
  var req = 4.82, lat = 14.2;
  setInterval(function() {
    if (reqElem) reqElem.textContent = (req += (Math.random() - 0.48) * 0.05).toFixed(2) + ' M req/s';
    if (latElem) latElem.textContent = (lat += (Math.random() - 0.5) * 0.4).toFixed(1) + ' ms';
  }, 1500);

  document.querySelectorAll('.faq-item').forEach(function(item) {
    var q = item.querySelector('.faq-question');
    if (q) q.addEventListener('click', function() { item.classList.toggle('open'); });
  });

  var header = document.querySelector('header.site-header');
  var ticking = false;
  window.addEventListener('scroll', function() {
    if (!ticking) {
      window.requestAnimationFrame(function() {
        if (header) header.style.boxShadow = window.scrollY > 30 ? '0 10px 25px -5px rgba(0,0,0,0.5)' : 'none';
        ticking = false;
      });
      ticking = true;
    }
  }, { passive: true });
});
